INSERT INTO journal(acteur, changement, motif) VALUES
('cartographe','OpenStreetMap écarté comme source d''enrichissement — 2 rapprochements sur 64',
 'Testé avant d''être adopté. OSM cartographie les enseignes visibles — Deloitte, In Extenso, Cerfrance, Fiducial — et des cabinets suisses frontaliers. Notre cible est l''indépendant local. Les deux ensembles de noms ne se recoupent pas : ce n''est pas un défaut de réglage mais de couverture. L''agent est conservé hors boucle, sans coût, au cas où la couverture progresserait.'),
('fureteur','Diagnostic : le Fureteur n''est ni cassé ni lent, il a épuisé la matière facile',
 '62 prospects ont un site sans adresse — le chemin rapide. 2 436 n''ont ni l''un ni l''autre et exigent la recherche par moteur, lente et à faible rendement. Aucune source gratuite testée ce soir ne remplace ce chemin. Conclusion honnête : il n''existe pas de raccourci gratuit vers 2 436 adresses.');
